const page=document.body.dataset.page||'owner';
const params=new URLSearchParams(location.search);
let language=params.get('lang')==='ur'?'ur':'en',state=params.get('state')||'ready',period='7',managerTab='tasks',locationTab='overview',mobileTab='day',captureStep='guide';
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',today:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18m-13 5 2 2 5-5"/>',camera:'<path d="M8 5 6 8H3v12h18V8h-3l-2-3Z"/><circle cx="12" cy="13" r="3"/>',building:'<path d="M4 21V5h11v16M15 10h5v11M2 21h20M8 9h3M8 13h3M8 17h3"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m2-16a3 3 0 0 1 0 6m2 10v-3a6 6 0 0 0-2-4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',chevron:'<path d="m9 5 7 7-7 7"/>',alert:'<path d="m12 3 10 18H2Zm0 6v5m0 3v.1"/>',shield:'<path d="m12 3 8 3v6c0 4-4 7-8 9-4-2-8-5-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M5 8a8 8 0 0 1 13-3l2 2M4 17l2 2a8 8 0 0 0 13-3"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 4m0 3v.1"/>',qr:'<path d="M3 3h6v6H3Zm12 0h6v6h-6ZM3 15h6v6H3Zm12 0h3v3h3v3h-6Zm6-3v3M12 3v9H3m9 3v6m3-9h6"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',card:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 10h18M7 15h4"/>',logout:'<path d="M9 4H4v16h5m5-4 4-4-4-4m-5 4h13"/>'};
const icon=k=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[k]||icons.grid}</svg>`;
const text=s=>`<span data-i18n>${s}</span>`;
const badge=(s,tone='')=>`<span class="badge ${tone}"><i class="dot" aria-hidden="true"></i>${text(s)}</span>`;
const btn=(s,action,primary=false,ic='')=>`<button type="button" class="btn ${primary?'primary':''}" data-action="${action}">${ic?icon(ic):''}${text(s)}</button>`;
const link=(s,file,ic='arrow')=>`<a class="text-link" href="${file}.html${language==='ur'?'?lang=ur':''}">${text(s)}${icon(ic)}</a>`;
const brand=()=>`<a href="owner.html" class="brand"><img src="assets/logo.svg" alt="" width="34" height="34"><span>Hygene Ops</span></a>`;
const lang=()=>`<div class="lang" role="group" aria-label="Language"><button type="button" data-lang="en" aria-pressed="${language==='en'}">English</button><button type="button" data-lang="ur" aria-pressed="${language==='ur'}" lang="ur">اردو</button></div>`;
const navItems=[['owner','grid','Overview'],['manager','today','Today'],['manager#reviews','camera','Photo reviews'],['location','building','Locations'],['team','users','Team'],['attendance','clock','Attendance']];
function nav(){return `<div class="nav-list">${navItems.map(([file,i,s])=>`<a href="${file.includes('#')?'manager.html#reviews':file+'.html'}${language==='ur'&&!file.includes('#')?'?lang=ur':''}" class="${file===page?'active':''}" ${file===page?'aria-current="page"':''}>${icon(i)}${text(s)}${s==='Photo reviews'?'<span class="count">5</span>':''}</a>`).join('')}</div>`;}
const reviewTools=()=>`<aside class="review-tools" aria-label="Prototype review controls"><div class="flex"><a href="index.html">${text('All screens')}</a><span class="review-desc">${text('Design review · Sample data')}</span></div><label class="flex">${text('State')}<select id="demo-state" aria-label="Prototype state">${[['ready','Sample data'],['loading','Loading'],['empty','Empty'],['error','Error'],['stale','Stale data'],['denied','No access']].map(([v,s])=>`<option value="${v}" ${state===v?'selected':''}>${s}</option>`).join('')}</select></label></aside>`;
function shell(content){const manager=page==='manager';return `${reviewTools()}<a class="skip" href="#main">${text('Skip to content')}</a><aside class="sidebar">${brand()}<div class="workspace-name"><strong>Saaf Facilities</strong>${text(manager?'Manager workspace':'Company workspace')}</div>${nav()}<div class="nav-extra">${btn('Account & billing','account',false,'card')}</div><div class="side-bottom"><div class="side-note">${text('A clearer view of every working day.')}</div><div class="account"><span class="avatar">${manager?'HK':'AS'}</span><div><strong>${manager?'Hassan Khan':'Ayesha Siddiqui'}</strong><small>${text(manager?'Site manager':'Company owner')}</small></div></div></div></aside><div class="workspace"><header class="topbar"><div class="flex"><details class="menu"><summary aria-label="Open navigation">${icon('menu')}</summary><nav aria-label="Mobile navigation">${nav()}</nav></details><span class="crumb">Saaf Facilities <span aria-hidden="true"> / </span> ${text(titles[page])}</span></div><div class="flex">${lang()}<div class="account"><span class="avatar">${manager?'HK':'AS'}</span><div><strong>${manager?'Hassan':'Ayesha'}</strong><small>${text(manager?'Site manager':'Company owner')}</small></div></div></div></header><main class="content" id="main" tabindex="-1">${content}<footer class="page-footer"><span>${icon('clock')} ${text('Sample snapshot · 20 Oct 2026, 10:30 PKT')}</span><span>${text('Dates follow each site’s local calendar day.')}</span></footer></main></div>`;}
const titles={owner:'Overview',manager:'Today',team:'Team',location:'Locations',attendance:'Attendance',mobile:'Staff app'};
function heading(h,p,actions=''){return `<div class="page-heading"><div><h1>${text(h)}</h1><p>${text(p)}</p></div>${actions}</div>`;}
function siteScope(single=false){return `<div class="scope"><div class="field"><label for="site">${text('Location')}</label><select id="site"><option>${single?'Gulberg office':'All locations'}</option>${single?'':'<option>Gulberg office</option><option>DHA facilities</option>'}</select></div><div class="field"><label for="date">${text('Local date')}</label><input id="date" type="date" value="2026-10-20"></div></div>`;}
function panel(h,p,body,action=''){return `<section class="panel"><div class="panel-head"><div><h2>${text(h)}</h2>${p?`<p>${text(p)}</p>`:''}</div>${action}</div>${body}</section>`;}
function metrics(items){return `<section class="summary-band" aria-label="Summary">${items.map(([label,value,desc,delta])=>`<div class="summary-item">${text(label)}<strong class="value">${value}</strong><p>${text(desc)}</p>${delta?`<span class="change">${text(delta)}</span>`:''}</div>`).join('')}</section>`;}
function stateContent(){if(state==='ready'||state==='stale')return '';if(state==='loading')return `<section class="panel" aria-busy="true" aria-label="Loading"><div class="state-skeleton"><h2>${text('Loading your workspace…')}</h2><div class="skeleton"></div><div class="skeleton short"></div><div class="skeleton wide"></div><p class="muted">${text('Your filters will stay in place.')}</p></div></section>`;const values={empty:['building','No records for this view','Try another date or location. No results does not mean a failed load.','Reset filters'],error:['alert','We couldn’t load this view','Your records have not changed. Check your connection and try again.','Try again'],denied:['shield','This view isn’t available to your account','Ask your company owner to check your assigned locations.','Back to overview']};const [ic,h,p,b]=values[state]||values.error;return panel('', '', `<div class="state-panel"><span class="state-symbol">${icon(ic)}</span><h2>${text(h)}</h2><p>${text(p)}</p>${btn(b,'reset',true)}</div>`);}
function staleNotice(){return state==='stale'?`<div class="notice" role="status">${icon('alert')}<div><strong>${text('Showing an earlier snapshot')}</strong><p>${text('The latest refresh failed. These figures are from 10:15 PKT.')}</p>${btn('Try again','reset')}</div></div>`:'';}
const sites=[['Gulberg office','Lahore · Hassan Khan','96.0%','88.0%','Needs attention','warn','3'],['DHA facilities','Lahore · Sana Ali','94.0%','90.0%','On track','good','0'],['Johar town','Lahore · Bilal Ahmed','90.0%','86.0%','In progress','blue','1'],['Model town','Lahore · Nadia Shah','88.0%','80.0%','Needs attention','warn','1']];
function rate(v,blue=false){return `<span class="rate"><strong>${v}</strong><span class="rate-track" aria-hidden="true"><span class="rate-fill ${blue?'blue':''}" style="display:block;width:${parseFloat(v)}%"></span></span></span>`;}
function chart(){const points=[['14 Oct',30,32,24,30],['15 Oct',32,34,26,31],['16 Oct',31,34,27,32],['17 Oct',33,35,29,34],['18 Oct',31,34,28,32],['19 Oct',30,33,29,33],['20 Oct',34,38,33,36]];return `<div class="panel-body"><div class="legend"><span><i class="line-key"></i>${text('Attendance')}</span><span><i class="line-key blue"></i>${text('Work submitted')}</span></div><svg class="chart" viewBox="0 0 620 238" role="img" aria-label="Daily attendance and work submission rates; exact values below" dir="ltr"><path class="grid" d="M48 24H602M48 80H602M48 136H602M48 192H602"/><text x="0" y="29">100%</text><text x="8" y="85">75%</text><text x="8" y="141">50%</text><text x="8" y="197">25%</text><path d="M48 39 140 37 232 44 324 37 416 44 508 45 600 48V192H48Z" fill="var(--mint)"/><polyline class="attendance" points="48,39 140,37 232,44 324,37 416,44 508,45 600,48"/><polyline class="submitted" points="48,69 140,60 232,58 324,57 416,51 508,46 600,43"/>${points.map((p,i)=>`<text x="${48+i*92}" y="226" text-anchor="middle">${p[0].split(' ')[0]}</text>`).join('')}</svg><p class="chart-caption">${text('14–20 Oct · Daily rates, not cumulative totals')}</p><details class="all-figures"><summary>${text('View daily figures')}</summary><table class="site-table"><caption class="muted">${text('Daily scheduled and received work')}</caption><thead><tr><th>${text('Day')}</th><th>${text('Attendance')}</th><th>${text('Work submitted')}</th></tr></thead><tbody>${points.map(p=>`<tr><td>${p[0]}</td><td data-label="Attendance">${p[1]} / ${p[2]}</td><td data-label="Work submitted">${p[3]} / ${p[4]}</td></tr>`).join('')}</tbody></table></details></div>`;}
function attention(){return `<div class="attention">${[['users','3 missed check-ins','Gulberg office · Today','attendance'],['camera','5 photo reviews','Across your locations · Open','manager'],['clock','2 overdue tasks','Gulberg office · Today','manager']].map(([ic,h,p,to])=>`<a class="attention-item" href="${to}.html"><span class="issue-icon">${icon(ic)}</span><div><strong>${text(h)}</strong><p>${text(p)}</p></div><span class="end" aria-label="Open">${icon('arrow')}</span></a>`).join('')}</div>`;}
function owner(){const filtered=stateContent();return shell(heading('Company performance','See what is working. Know where to focus next.',siteScope())+filtered+(filtered?'':staleNotice()+`<div class="toolbar"><div class="segmented" role="group" aria-label="Reporting period"><button type="button" data-period="7" aria-pressed="${period==='7'}">${text('Last 7 days')}</button><button type="button" data-period="30" aria-pressed="${period==='30'}">${text('Last 30 days')}</button></div><span class="scope-summary" id="range">${text(period==='7'?'14–20 Oct 2026':'21 Sep–20 Oct 2026')}</span>${btn('Refresh','refresh',false,'refresh')}</div>`+metrics(period==='7'?[['Attendance','92.1%','221 / 240 scheduled shifts','+2.4 pp from previous period'],['Work submitted','86.0%','196 / 228 scheduled tasks','+3.1 pp from previous period'],['Active locations','4 <small>/ 4</small>','38 active team members','All locations included'],['Open photo reviews','5','For work in this period','Review does not mean verified']]:[['Attendance','91.0%','910 / 1,000 scheduled shifts','30-day sample'],['Work submitted','84.0%','840 / 1,000 scheduled tasks','30-day sample'],['Active locations','4 <small>/ 4</small>','38 active team members','All locations included'],['Open photo reviews','5','For work in this period','Review does not mean verified']])+`<div class="dashboard-grid">${panel('Consistency over time','A clearer picture of attendance and submitted work.',period==='7'?chart():`<div class="panel-body"><p>${text('30-day sample · Daily detail is available in the production report.')}</p>${link('View daily operations','manager')}</div>`)}${panel('Needs attention today','20 Oct · Site-local dates',attention(),badge('10 items','warn'))}</div>`+panel('Every location, in focus','Rates cover the reporting period. Status describes the selected day.',`<div class="table-tools"><label class="search">${icon('search')}<input id="site-search" placeholder="Find a location" aria-label="Find a location"></label>${link('Manage locations','location')}</div><table class="site-table"><thead><tr>${['Location','Attendance','Work submitted','Today’s status','Reviews',''].map(s=>`<th scope="col">${text(s)}</th>`).join('')}</tr></thead><tbody id="sites">${sites.map(([n,sub,a,w,status,tone,reviews])=>`<tr data-search="${n.toLowerCase()}"><td><a href="location.html" class="record-title">${n}</a><div class="record-sub">${sub}</div></td><td data-label="Attendance">${rate(a)}</td><td data-label="Work submitted">${rate(w,true)}</td><td data-label="Today’s status">${badge(status,tone)}</td><td data-label="Open reviews">${reviews}</td><td><a class="btn quiet" href="location.html" aria-label="Open ${n}">${icon('arrow')}</a></td></tr>`).join('')}</tbody></table><div id="no-search" class="state-panel" hidden><h3>${text('No matching locations')}</h3>${btn('Clear search','clear-search')}</div><div class="panel-footer"><span id="site-count">${text('4 locations · Weighted company totals')}</span>${link('Open today’s operations','manager')}</div>`)));}
const tasks=[['Ground-floor washrooms','Gulberg office · 09:00–10:00','Ali Raza','Submitted','good','Review photos'],['Entrance & lobby','Gulberg office · 10:00–11:00','Sadia Noor','In progress','blue','Task details'],['Second-floor washrooms','Gulberg office · 09:30–10:30','Usman Tariq','Overdue','bad','Task details']];
function reviewDetail(){return `<div class="review-detail" id="review-detail" hidden><div class="flex between wrap"><h2>${text('Ground-floor washrooms')}</h2>${btn('Close detail','close-review')}</div><p class="muted">Ali Raza · Gulberg office · 20 Oct</p><div class="notice" style="margin-top:20px"><div><strong>${text('What needs attention')}</strong><p>${text('The basin photo could not be assessed. This is not a dirty finding.')}</p></div></div><div class="detail-grid"><div class="evidence-placeholder">${icon('shield')}<strong>${text('Protected task photo')}</strong><p>${text('Photo access is checked by the server. This prototype contains no workforce photos.')}</p></div><div><h3>${text('Work submitted · Review open')}</h3><p class="muted">${text('Closing this review does not verify the task or change its required photos.')}</p><form id="review-form"><div class="field"><label for="review-note">${text('Resolution note (required)')}</label><textarea id="review-note" required></textarea></div><p id="review-error" class="form-error" role="alert"></p><button class="btn primary" type="submit">${text('Close review with note')}</button><div id="review-success" class="feedback" role="status" hidden>${text('Demo review closed. Task verification is unchanged.')}</div></form></div></div></div>`;}
function manager(){const filtered=stateContent();return shell(heading('A clear plan for today','Your assigned locations, the work in motion, and the next decision.',siteScope(true))+filtered+(filtered?'':staleNotice()+`<div class="notice">${icon('alert')}<div><strong>${text('3 people have not checked in')}</strong><p>${text('Gulberg office · Scheduled for today. Check attendance before reassigning work.')}</p>${link('Check attendance','attendance')}</div></div>`+metrics([['Scheduled team','12','9 checked in · 3 missing','Today · Gulberg office'],['Tasks today','14','8 submitted · 4 in progress','2 overdue'],['Photo reviews','3','Waiting for your decision','Submission is recorded separately'],['Next task starts','11:00','Entrance & lobby','Site time · Asia/Karachi']])+`<div class="tabs" role="tablist" aria-label="Today’s work"><button role="tab" aria-selected="${managerTab==='tasks'}" data-manager-tab="tasks">${text('Tasks')} <span>14</span></button><button role="tab" aria-selected="${managerTab==='reviews'}" data-manager-tab="reviews">${text('Photo reviews')} <span>3</span></button><button role="tab" aria-selected="${managerTab==='staff'}" data-manager-tab="staff">${text('Staff')} <span>12</span></button></div>`+(managerTab==='staff'?staffTable(true):panel(managerTab==='reviews'?'Photo reviews':'Today’s tasks',managerTab==='reviews'?'Read the reason, inspect the photos, and record a decision.':'The next action stays visible for each task.',`<div class="task-list">${tasks.filter((_,i)=>managerTab!=='reviews'||i===0).map(([h,p,n,s,t,b])=>`<article class="task-row"><div class="task-info"><h3>${text(h)}</h3><p>${text(p)}</p></div><div class="person-col">${n}<p>${text('Assigned staff')}</p></div><div>${badge(s,t)}</div>${btn(b,'review',false,b==='Review photos'?'camera':'arrow')}</article>`).join('')}</div>${reviewDetail()}<div class="panel-footer"><span>${text('Showing sample tasks from your assigned site')}</span>${link('View schedule','location')}</div>`))));}
function staffForm(){return `<section class="panel form-panel" id="staff-form-panel" hidden><h2>${text('Add a team member')}</h2><p class="muted">${text('Managers must choose one of their assigned sites.')}</p><form id="staff-form" novalidate><div class="form-grid" style="margin-top:24px"><div class="field"><label for="staff-name">${text('Full name')}</label><input id="staff-name" required autocomplete="off"><p class="form-error" id="name-error"></p></div><div class="field"><label for="staff-email">${text('Email')}</label><input id="staff-email" type="email" dir="ltr" required><p class="form-error" id="email-error"></p></div><div class="field"><label for="staff-site">${text('Assigned site')}</label><select id="staff-site" required><option value="">${text('Choose a site')}</option><option>Gulberg office</option><option>DHA facilities</option></select><p class="form-error" id="location-error"></p></div><div class="field"><label for="staff-shift">${text('Shift')}</label><select id="staff-shift"><option>08:00–16:00</option><option>16:00–00:00</option></select><p class="small muted">${text('Times use the site’s timezone.')}</p></div></div><p class="small muted">${text('Demo form: credential setup follows the existing account workflow in implementation.')}</p><div class="form-actions">${btn('Cancel','cancel-staff')}<button class="btn primary" type="submit">${text('Add team member')}</button></div><div class="feedback" id="staff-success" role="status" hidden>${text('Added to this demo. No real account was created.')}</div></form></section>`;}
const workers=[['AR','Ali Raza','Gulberg office','08:00–16:00','Checked in','good','2 / 3'],['SN','Sadia Noor','Gulberg office','08:00–16:00','Checked in','good','1 / 3'],['UT','Usman Tariq','Gulberg office','08:00–16:00','Not checked in','bad','0 / 2'],['FM','Fatima Malik','DHA facilities','09:00–17:00','Checked in','good','3 / 4']];
function staffTable(scoped=false){return panel(scoped?'Your site team':'Your people, at a glance','Attendance and work for the selected local day.',`<div class="table-tools"><label class="search">${icon('search')}<input id="staff-search" placeholder="Find a team member" aria-label="Find a team member"></label><span class="scope-summary">${text(scoped?'Gulberg office · 12 team members':'4 sample records · 38 team members overall')}</span></div><table class="site-table"><thead><tr>${['Team member','Location & shift','Attendance','Tasks submitted',''].map(s=>`<th>${text(s)}</th>`).join('')}</tr></thead><tbody id="workers">${workers.filter((_,i)=>!scoped||i<3).map(([inits,n,l,shift,s,t,tasks])=>`<tr data-search="${n.toLowerCase()}"><td><div class="flex"><span class="avatar">${inits}</span><div><strong class="record-title">${n}</strong><p class="record-sub">${text('Staff')}</p></div></div></td><td data-label="Location & shift">${l}<p class="record-sub" dir="ltr">${shift}</p></td><td data-label="Attendance">${badge(s,t)}</td><td data-label="Tasks submitted">${tasks}</td><td>${btn('View details','staff-detail',false,'arrow')}</td></tr>`).join('')}</tbody></table><div class="feedback" id="staff-detail" hidden role="status">${text('Selected staff details appear here in the production app. This concept establishes the directory and form pattern.')}</div><div class="panel-footer"><span id="worker-count">${text('Sample directory · Search filters these records')}</span>${link('Open attendance','attendance')}</div>`);}
function team(){const filtered=stateContent();return shell(heading('Your team','The right people, in the right place, with a clear working day.',btn('Add team member','add-staff',true,'plus'))+filtered+(filtered?'':staleNotice()+metrics([['Active staff','38','Across 4 locations','Company-wide scope'],['Checked in today','35 <small>/ 38</small>','Includes late arrivals','3 not checked in'],['Managers','4','One manager per location','Assigned-site access'],['Unassigned hires','0','Owners can stage new hires','Managers must choose a site']])+`<div class="stack">${staffForm()}${staffTable()}</div>`));}
function locationScreen(){const filtered=stateContent();return shell(`<div class="page-heading"><div class="location-intro"><span class="location-symbol">${icon('building')}</span><div><h1>Gulberg office</h1><p>Lahore · Asia/Karachi · ${text('Managed by')} Hassan Khan</p></div></div>${btn('Edit location','edit-location',false,'pin')}</div>`+filtered+(filtered?'':staleNotice()+`<div class="tabs" role="tablist" aria-label="Location sections">${[['overview','Overview'],['team','Team'],['schedule','Schedule'],['areas','Area templates'],['history','Task history']].map(([v,s])=>`<button role="tab" data-location-tab="${v}" aria-selected="${v===locationTab}">${text(s)}</button>`).join('')}</div><div id="location-tab-content">${locationContent()}</div><div id="location-feedback" class="feedback" role="status" hidden>${text('Demo only. Location edits keep the existing map, geofence and timezone workflow.')}</div>`));}
function locationContent(){if(locationTab==='team')return staffTable(true);if(locationTab==='schedule')return panel('Today’s schedule','20 Oct · Asia/Karachi · Actual tasks have their own task QR.',`<div class="task-list">${tasks.map(([h,p,n,s,t])=>`<div class="task-row"><div class="task-info"><h3>${text(h)}</h3><p>${text(p)}</p></div><div class="person-col">${n}</div>${badge(s,t)}${btn('View task QR','task-qr',false,'qr')}</div>`).join('')}</div><div id="task-qr-feedback" class="feedback" hidden role="status">${text('The production app shows a signed code for this exact task. No usable QR is included in this prototype.')}</div>`);if(locationTab==='areas')return panel('Area templates','Reusable fixture requirements. Existing task snapshots stay unchanged.',`<div class="panel-body"><details><summary class="text-link">${text('Ground-floor washrooms · 3 fixtures')}</summary><dl class="fact-list"><div><dt>${text('Basin')}</dt><dd>${text('Front view')}</dd></div><div><dt>${text('Toilet')}</dt><dd>${text('Inside bowl')}</dd></div><div><dt>${text('Floor')}</dt><dd>${text('Wide view')}</dd></div></dl></details><p class="muted small">${text('Area creation and editing stay inline in this tab.')}</p></div>`);if(locationTab==='history')return panel('Task history','Submission, review and verification remain separate.',`<div class="panel-body"><dl class="fact-list"><div><dt>20 Oct · ${text('Ground-floor washrooms')}</dt><dd>${badge('Review open','warn')}</dd></div><div><dt>19 Oct · ${text('Entrance & lobby')}</dt><dd>${badge('Verified','good')}</dd></div></dl>${link('Open photo reviews','manager')}</div>`);return metrics([['Staff today','12','9 checked in · 3 missing','Site-local day'],['Tasks submitted','8 <small>/ 14</small>','4 in progress · 2 overdue','Submission is not verification'],['Photo reviews','3','Waiting for a decision','View reviews'],['Area templates','4','Reusable cleaning requirements','Immutable task snapshots']])+`<div class="detail-grid">${panel('Today at this location','Start with the exceptions, then check the schedule.',attention())}${panel('Location details','The facts used by attendance and scheduling.',`<div class="panel-body"><dl class="fact-list"><div><dt>${text('Manager')}</dt><dd>Hassan Khan</dd></div><div><dt>${text('Timezone')}</dt><dd>Asia/Karachi</dd></div><div><dt>${text('Check-in radius')}</dt><dd>150 m</dd></div><div><dt>${text('Working shift')}</dt><dd dir="ltr">08:00–16:00</dd></div></dl><p class="small muted" style="margin-top:20px">${text('Attendance uses the saved geofence and reported device location.')}</p></div>`)}</div>`;}
function attendance(){const filtered=stateContent();return shell(heading('Attendance','Know who is on site. Follow every check-in with confidence.')+`<form class="panel form-panel" id="attendance-filter" style="margin-bottom:24px"><div class="flex wrap between"><div class="scope"><div class="field"><label for="attendance-site">${text('Location')}</label><select id="attendance-site"><option>Gulberg office</option><option>DHA facilities</option></select></div><div class="field"><label for="from">${text('From')}</label><input id="from" type="date" value="2026-10-20" required></div><div class="field"><label for="to">${text('To')}</label><input id="to" type="date" value="2026-10-20" required></div></div><button type="submit" class="btn primary">${text('Apply filters')}</button></div><p id="filter-error" class="form-error" role="alert"></p><div class="flex between wrap" style="margin-top:8px"><span class="scope-summary" id="applied-scope">Gulberg office · 20 Oct 2026 · Asia/Karachi</span>${btn('Today','today')}</div></form>`+filtered+(filtered?'':staleNotice()+metrics([['Scheduled shifts','12','For the applied local date','Includes upcoming shifts'],['Checked in','9','Including 1 late arrival','3 not checked in'],['Late arrivals','1','Still counted as present','Recorded against the shift'],['Checked out','0','No completed shifts yet','Measured result']])+panel('Today’s attendance','Photos are available only to authorized accounts.',`<table class="site-table"><thead><tr>${['Staff member','Shift','Check-in','Status','Photo'].map(s=>`<th>${text(s)}</th>`).join('')}</tr></thead><tbody>${workers.slice(0,3).map(([inits,n,l,shift,s,t],i)=>`<tr><td><div class="flex"><span class="avatar">${inits}</span><strong class="record-title">${n}</strong></div></td><td data-label="Shift"><span dir="ltr">${shift}</span></td><td data-label="Check-in">${i===0?'07:56':i===1?'08:12':'—'}</td><td data-label="Status">${badge(i===1?'Late arrival':s,i===1?'warn':t)}</td><td>${i<2?btn('View photo','attendance-photo',false,'shield'):text('No photo')}</td></tr>`).join('')}</tbody></table><div id="photo-feedback" class="feedback" role="status" hidden>${text('Protected attendance photo: the backend must authorize company, assigned site or self access. No selfie is embedded in this prototype.')}</div><div class="panel-footer"><span>${text('3 sample records · Totals cover the complete site')}</span><span>${text('Overnight shifts remain tied to their scheduled local date.')}</span></div>`)));}
function mobile(){let body='';if(stateContent())body=stateContent();else if(mobileTab==='help')body=`<h1>${text('Help & account')}</h1><div class="native-task"><h2>${text('Task alerts')}</h2><p>${text('Alerts are off for this phone. You can still check your tasks here.')}</p>${btn('Check alert settings','alert-settings',true)}<div id="alert-feedback" class="feedback" role="status" hidden>${text('Demo: open Android notification settings, then return and try again.')}</div></div><div class="native-task"><h2>Ali Raza</h2><p>Gulberg office</p><p class="muted">${text('Ask your manager if you need help with your account.')}</p></div>`;else if(mobileTab==='photos')body=photoFlow();else if(mobileTab==='tasks')body=`<h1>${text('Your tasks')}</h1>${nativeTask()}<div class="native-task">${badge('Next','blue')}<h2>${text('Entrance & lobby')}</h2><p>${text('Starts at 11:00 · Gulberg office')}</p><p class="muted">${text('Your next task will be available at its start time.')}</p></div>`;else body=`<div><p class="muted">${text('Tuesday, 20 October')}</p><h1>${text('A good start, Ali.')}</h1><p class="muted">Gulberg office</p></div><section class="shift-info"><div class="flex between">${badge('Checked in','good')}${icon('check')}</div><h2>${text('You’re on site.')}</h2><p>${text('Checked in at 07:56')}</p><p>${text('Your shift')} <bdi>08:00–16:00</bdi></p></section><div class="flex between"><h2>${text('Your next step')}</h2><span class="muted small">${text('1 of 3 tasks')}</span></div>${nativeTask()}<p class="small muted">${icon('shield')} ${text('Only you and authorized company managers can see your attendance photo.')}</p>`;return `${reviewTools()}<a class="skip" href="#main">${text('Skip to content')}</a><div class="native-canvas"><div class="phone"><header class="phone-top"><div class="flex between">${brand()}${lang()}</div></header><main class="phone-body" id="main" tabindex="-1">${staleNotice()}${body}</main><nav class="bottom-tabs" aria-label="Staff navigation">${[['day','today','My day'],['tasks','grid','Tasks'],['help','help','Help & account']].map(([v,i,s])=>`<button type="button" data-mobile-tab="${v}" role="tab" aria-selected="${mobileTab===v}">${icon(i)}${text(s)}</button>`).join('')}</nav></div></div>`;}
function nativeTask(){return `<section class="native-task">${badge('Ready to start','blue')}<h2>${text('Ground-floor washrooms')}</h2><p>${text('09:00–10:00 · 3 required photos')}</p><p class="muted" style="margin-top:8px">${text('Scan this task’s QR code to start cleaning.')}</p>${btn('Scan task QR','scan',true,'qr')}</section>`;}
function photoFlow(){if(captureStep==='submitted')return `<div class="shift-info">${icon('check')}<h1>${text('Work submitted.')}</h1><p>${text('Your manager may still need to review the photos.')}</p></div><p>${text('You have finished your part. Verification is recorded separately.')}</p>${btn('Back to my day','my-day',true)}`;if(captureStep==='qr')return `<h1>${text('Scan the task QR')}</h1><p>${text('Use the code for Ground-floor washrooms. A room or fixture code will not work.')}</p><div class="photo-illustration">${icon('qr')}<span>${text('Camera preview · Demo')}</span></div><p class="muted">${text('Camera access is required on your Android phone.')}</p>${btn('Simulate valid scan','valid-qr',true)}${btn('Back to tasks','back-tasks')}`;if(captureStep==='started')return `<h1>${text('Cleaning started.')}</h1><p>${text('Clean the area first. Then scan the same task QR again to take photos.')}</p>${btn('Scan QR for photos','photo-qr',true,'qr')}<p class="small muted">${text('This demo simulates the second authorized scan. The real app checks task, assignment and timing.')}</p>`;return `<div><div class="step-line"><span>${text('Required photos')}</span><span>${captureStep==='complete'?'3':'1'} / 3</span></div><div class="task-progress"><span class="done"></span><span class="${captureStep==='complete'?'done':''}"></span><span class="${captureStep==='complete'?'done':''}"></span></div><h1>${text(captureStep==='complete'?'All photos checked.':'Basin · Front view')}</h1></div>${captureStep==='complete'?`<div class="shift-info"><h2>${text('Your work is ready to submit.')}</h2><p>${text('3 photos received and checked. Manager review may still be needed.')}</p></div>${btn('Submit work','submit-work',true)}`:`<div class="photo-illustration"><svg viewBox="0 0 280 180" fill="none" aria-hidden="true"><path d="M30 150V45h220v105" stroke="#7d9690" stroke-width="2"/><path d="M80 100h120l-12 35H92Z" fill="#f5f7f4" stroke="#68817c" stroke-width="3"/><ellipse cx="140" cy="102" rx="56" ry="13" fill="#f5f7f4" stroke="#68817c" stroke-width="3"/><path d="M130 88V58h20v20m-10 56v23M105 157h70M18 20h28M18 20v28m244-28h-28m28 0v28M18 160h28m-28 0v-28m244 28h-28m28 0v-28" stroke="#126353" stroke-width="3" stroke-linecap="round"/></svg><span>${text('Framing guide · Illustration')}</span></div><section class="photo-guide"><h2>${text('Show the whole basin.')}</h2><ul><li>${text('Include the tap and inside surface.')}</li><li>${text('Keep people and reflections out of the photo.')}</li><li>${text('Hold the phone steady in good light.')}</li></ul></section><p class="timer">${icon('clock')} ${text('Photo window: 01:42 remaining · Sample timer')}</p>${captureStep==='retry'?`<div class="notice" role="alert"><div><strong>${text('The response was lost.')}</strong><p>${text('Check the result first. Your photo may have reached the server.')}</p></div></div>${btn('Check result','check-result',true,'refresh')}${btn('Retry upload','check-result')}`:`${btn('Take photo','take-photo',true,'camera')}${btn('Simulate lost response','lost-response')}`}`}<p class="small muted">${text('Internet is required. Leaving this screen discards any temporary photo.')}</p>`;}
function gallery(){return `<main class="gallery"><div class="flex between wrap" style="margin-bottom:40px">${brand()}${lang()}</div><span class="demo-label">${text('Visual direction · Awaiting approval')}</span><h1>${text('A clearer working day.')}</h1><p>${text('Six connected views for Hygene Ops. Explore the layout, switch languages, and try the sample interactions. All data is fictional; nothing connects to your application.')}</p><div class="gallery-grid">${[['owner','grid','Owner overview','Performance, location comparisons and today’s attention.'],['manager','today','Manager workspace','Daily tasks, staff and reason-first photo reviews.'],['team','users','Team management','A readable directory and a clear staff creation pattern.'],['location','building','Location workspace','One home for the team, schedule and area requirements.'],['attendance','clock','Attendance','Clear local-day filters and protected photo access.'],['mobile','camera','Staff mobile app','My day, tasks, guided photos and explicit retry.']].map(([file,i,h,p])=>`<a class="gallery-link" href="${file}.html${language==='ur'?'?lang=ur':''}">${icon(i)}<div><h2>${text(h)}</h2><p>${text(p)}</p></div>${icon('arrow')}</a>`).join('')}</div><div class="gallery-foot"><p>${text('Review at desktop and phone widths. Use State on each screen to inspect loading, empty, error and access states.')}</p><p style="margin-top:12px">${text('Prototype only. Native camera, GPS, secure storage, billing and server permissions require separate implementation and device verification.')}</p></div></main>`;}
function render(){document.documentElement.lang=language==='ur'?'ur-PK':'en';document.documentElement.dir=language==='ur'?'rtl':'ltr';document.title=(titles[page]||'Design review')+' · Hygene Ops';document.getElementById('app').innerHTML=({owner,manager,team,location:locationScreen,attendance,mobile,index:gallery}[page]||owner)();translate();wire();}
function wire(){document.querySelectorAll('[data-lang]').forEach(el=>el.onclick=()=>{language=el.dataset.lang;render()});document.getElementById('demo-state')?.addEventListener('change',e=>{state=e.target.value;render()});document.querySelectorAll('[data-period]').forEach(el=>el.onclick=()=>{period=el.dataset.period;render()});document.querySelectorAll('[data-manager-tab]').forEach(el=>el.onclick=()=>{managerTab=el.dataset.managerTab;render()});document.querySelectorAll('[data-location-tab]').forEach(el=>el.onclick=()=>{locationTab=el.dataset.locationTab;render()});document.querySelectorAll('[data-mobile-tab]').forEach(el=>el.onclick=()=>{mobileTab=el.dataset.mobileTab;render()});document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>act(el.dataset.action));document.getElementById('site-search')?.addEventListener('input',e=>filterRows('sites',e.target.value,'no-search'));document.getElementById('staff-search')?.addEventListener('input',e=>filterRows('workers',e.target.value));document.getElementById('staff-form')?.addEventListener('submit',e=>{e.preventDefault();const errors=[['staff-name','name-error','Enter a full name.',v=>v.trim().length>1],['staff-email','email-error','Enter a valid email address.',v=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)],['staff-site','location-error','Choose an assigned site.',Boolean]];let first;for(const [id,error,message,valid] of errors){const input=document.getElementById(id),bad=!valid(input.value);document.getElementById(error).textContent=bad?tr(message):'';input.setAttribute('aria-invalid',String(bad));input.setAttribute('aria-describedby',error);if(bad&&!first)first=input;}if(first)first.focus();else show('staff-success')});document.getElementById('review-form')?.addEventListener('submit',e=>{e.preventDefault();show('review-success')});document.getElementById('attendance-filter')?.addEventListener('submit',e=>{e.preventDefault();const from=document.getElementById('from').value,to=document.getElementById('to').value;document.getElementById('filter-error').textContent=from>to?tr('The end date must be on or after the start date.'):'';if(from>to)document.getElementById('to').focus();else document.getElementById('applied-scope').textContent=document.getElementById('attendance-site').value+' · '+from+' – '+to+' · Asia/Karachi'});}
function filterRows(id,q,empty){let count=0;document.querySelectorAll(`#${id} tr`).forEach(row=>{row.hidden=!row.dataset.search.includes(q.toLowerCase());if(!row.hidden)count++});if(empty)document.getElementById(empty).hidden=count>0;const counter=document.getElementById(id==='sites'?'site-count':'worker-count');if(counter&&q)counter.textContent=tr('Matching records')+': '+count;}
function show(id){const el=document.getElementById(id);if(el){el.hidden=false;el.scrollIntoView({block:'nearest'});}}
function act(a){if(['reset','refresh'].includes(a)){state='ready';render()}else if(a==='clear-search'){document.getElementById('site-search').value='';filterRows('sites','','no-search')}else if(a==='review')show('review-detail');else if(a==='close-review')document.getElementById('review-detail').hidden=true;else if(a==='add-staff')show('staff-form-panel');else if(a==='cancel-staff')document.getElementById('staff-form-panel').hidden=true;else if(a==='staff-detail')show('staff-detail');else if(a==='edit-location')show('location-feedback');else if(a==='task-qr')show('task-qr-feedback');else if(a==='attendance-photo')show('photo-feedback');else if(a==='alert-settings')show('alert-feedback');else if(a==='today'){document.getElementById('from').value='2026-10-20';document.getElementById('to').value='2026-10-20'}else if(a==='scan'){mobileTab='photos';captureStep='qr';render()}else if(a==='valid-qr'){captureStep='started';render()}else if(a==='photo-qr'){captureStep='guide';render()}else if(a==='take-photo'||a==='check-result'){captureStep='complete';render()}else if(a==='lost-response'){captureStep='retry';render()}else if(a==='submit-work'){captureStep='submitted';render()}else if(a==='my-day'){mobileTab='day';render()}else if(a==='back-tasks'){mobileTab='tasks';render()}else if(a==='account'){alert(tr('Account and billing keep the existing owner permissions. Detailed screens will follow this approved visual system.'))}}
function tr(s){return language==='ur'?(urdu[s]||s):s;}
function translate(){if(language!=='ur')return;document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=tr(el.textContent));document.querySelectorAll('[placeholder],[aria-label],[data-label]').forEach(el=>{for(const attr of ['placeholder','aria-label','data-label'])if(el.hasAttribute(attr))el.setAttribute(attr,tr(el.getAttribute(attr)))});document.querySelectorAll('option').forEach(el=>el.textContent=tr(el.textContent));}

